def tiene_duplicados_lento(datos):
    # Compara cada pareja: n·(n-1)/2 comparaciones -> O(n²)
    for i in range(len(datos)):
        for j in range(i + 1, len(datos)):
            if datos[i] == datos[j]:
                return True
    return False


def tiene_duplicados_rapido(datos):
    # Un recorrido y un set de vistos: O(n) de media (y O(n) de memoria extra)
    vistos = set()
    for x in datos:
        if x in vistos:
            return True
        vistos.add(x)
    return False


