import bisect


def primera_no_menor(a, x):
    """Como bisect_left: primer índice i con a[i] >= x (len(a) si no hay)."""
    lo, hi = 0, len(a)            # la respuesta está en [lo, hi]
    while lo < hi:
        medio = (lo + hi) // 2    # en Python los enteros no se desbordan
        if a[medio] < x:
            lo = medio + 1        # a[medio] y todo lo anterior son < x
        else:
            hi = medio            # a[medio] >= x: podría ser la respuesta
    return lo


