import math


def raiz_entera(n):
    """Mayor r con r*r <= n, buscando sobre las respuestas posibles."""
    lo, hi = 0, n + 1             # r está en [lo, hi): lo cumple, hi no
    while hi - lo > 1:
        medio = (lo + hi) // 2
        if medio * medio <= n:
            lo = medio
        else:
            hi = medio
    return lo


