def pareja_con_suma(ordenada, objetivo):
    i, j = 0, len(ordenada) - 1
    while i < j:
        s = ordenada[i] + ordenada[j]
        if s == objetivo:
            return ordenada[i], ordenada[j]
        if s < objetivo:
            i += 1                # necesito una suma mayor
        else:
            j -= 1                # me he pasado
    return None


