def es_palindromo(texto):
    """Dos punteros desde los extremos, ignorando lo que no sea letra o número."""
    i, j = 0, len(texto) - 1
    while i < j:
        if not texto[i].isalnum():
            i += 1
        elif not texto[j].isalnum():
            j -= 1
        elif texto[i].lower() != texto[j].lower():
            return False
        else:
            i, j = i + 1, j - 1
    return True


