def subcadena_sin_repetir(texto):
    """Longitud de la subcadena más larga sin caracteres repetidos. O(n)."""
    ultima_vez = {}               # carácter -> última posición en la que se vio
    izquierda = 0
    mejor = 0
    for derecha, caracter in enumerate(texto):
        if ultima_vez.get(caracter, -1) >= izquierda:
            izquierda = ultima_vez[caracter] + 1    # salta justo detrás del repetido
        ultima_vez[caracter] = derecha
        mejor = max(mejor, derecha - izquierda + 1)
    return mejor


