grafo = {"A": ["B", "C"], "B": ["D"], "C": ["D", "E"], "D": ["F"], "E": ["F"], "F": []}


def dfs_iterativo(grafo, origen):
    visitados, pila, orden = set(), [origen], []
    while pila:
        nodo = pila.pop()             # LIFO: el último que entra sale primero
        if nodo in visitados:
            continue
        visitados.add(nodo)
        orden.append(nodo)
        for vecino in reversed(grafo[nodo]):   # para visitarlos en su orden natural
            if vecino not in visitados:
                pila.append(vecino)
    return orden


def dfs_recursivo(grafo, nodo, visitados=None):
    if visitados is None:
        visitados = []
    visitados.append(nodo)
    for vecino in grafo[nodo]:
        if vecino not in visitados:
            dfs_recursivo(grafo, vecino, visitados)
    return visitados


print(dfs_iterativo(grafo, "A"))      # ['A', 'B', 'D', 'F', 'C', 'E']
print(dfs_recursivo(grafo, "A"))      # mismo orden

import heapq


def dijkstra(grafo, origen):
    """grafo: {nodo: [(vecino, peso), ...]} con pesos >= 0. Devuelve {nodo: distancia}."""
    distancia = {origen: 0}
    cola = [(0, origen)]
    while cola:
        d, nodo = heapq.heappop(cola)
        if d > distancia[nodo]:
            continue                  # entrada obsoleta: ya encontramos algo mejor
        for vecino, peso in grafo[nodo]:
            nueva = d + peso
            if nueva < distancia.get(vecino, float("inf")):
                distancia[vecino] = nueva
                heapq.heappush(cola, (nueva, vecino))
    return distancia


