from functools import cache


def monedas_minimas(monedas, cantidad):
    """Mínimo número de monedas para formar cantidad, o -1. De abajo arriba."""
    infinito = float("inf")
    mejor = [0] + [infinito] * cantidad      # mejor[c] = mínimo para formar c
    for c in range(1, cantidad + 1):
        for m in monedas:
            if m <= c and mejor[c - m] + 1 < mejor[c]:
                mejor[c] = mejor[c - m] + 1
    return mejor[cantidad] if mejor[cantidad] != infinito else -1


def monedas_minimas_memo(monedas, cantidad):
    """La misma recurrencia, de arriba abajo con memoización."""
    @cache
    def resolver(c):
        if c == 0:
            return 0
        opciones = [resolver(c - m) + 1 for m in monedas if m <= c]
        return min(opciones, default=float("inf"))
    resultado = resolver(cantidad)
    return resultado if resultado != float("inf") else -1


print(monedas_minimas([1, 5, 6, 9], 11))       # 2 (5 + 6); la estrategia voraz daría 9+1+1 = 3
print(monedas_minimas_memo([1, 5, 6, 9], 11))  # 2
