def media_movil(valores, k):
    if not isinstance(k, int) or k <= 0:
        raise ValueError("k debe ser un entero positivo")
    ventana = deque()
    suma = 0
    medias = []
    for x in valores:
        ventana.append(x)
        suma += x
        if len(ventana) > k:
            suma -= ventana.popleft()     # sale el más antiguo
        if len(ventana) == k:
            medias.append(suma / k)
    return medias

