import heapq


class TopK:
    def __init__(self, k):
        if not isinstance(k, int) or k < 1:
            raise ValueError("k debe ser un entero >= 1")
        self.k = k
        self._heap = []            # min-heap con, como mucho, k elementos

    def agregar(self, valor):
        if len(self._heap) < self.k:
            heapq.heappush(self._heap, valor)
        elif valor > self._heap[0]:
            heapq.heapreplace(self._heap, valor)   # saca la raíz y mete valor

    def umbral(self):
        return self._heap[0] if self._heap else None

    def top(self):
        return sorted(self._heap, reverse=True)

    def __len__(self):
        return len(self._heap)

