from collections import deque


def pasos_minimos(mapa):
    inicio = meta = None
    for f, fila in enumerate(mapa):
        for c, casilla in enumerate(fila):
            if casilla == "S":
                inicio = (f, c)
            elif casilla == "E":
                meta = (f, c)
    if inicio is None or meta is None:
        raise ValueError("El mapa necesita una 'S' y una 'E'")
    filas, columnas = len(mapa), len(mapa[0])
    distancia = {inicio: 0}                  # también marca las visitadas
    cola = deque([inicio])
    while cola:
        f, c = cola.popleft()
        if (f, c) == meta:
            return distancia[(f, c)]
        for nf, nc in ((f + 1, c), (f - 1, c), (f, c + 1), (f, c - 1)):
            if (0 <= nf < filas and 0 <= nc < columnas
                    and mapa[nf][nc] != "#" and (nf, nc) not in distancia):
                distancia[(nf, nc)] = distancia[(f, c)] + 1
                cola.append((nf, nc))
    return -1

