def mochila(objetos, capacidad):
    if capacidad < 0:
        raise ValueError("La capacidad no puede ser negativa")
    n = len(objetos)
    # mejor[i][c]: máximo valor con los i primeros objetos y capacidad c
    mejor = [[0] * (capacidad + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        _, peso, valor = objetos[i - 1]
        anterior, actual = mejor[i - 1], mejor[i]
        for c in range(capacidad + 1):
            actual[c] = anterior[c]                          # no llevar el objeto i
            if peso <= c and anterior[c - peso] + valor > actual[c]:
                actual[c] = anterior[c - peso] + valor       # llevarlo
    # Reconstrucción: si el valor cambió al considerar el objeto i, lo llevamos
    elegidos = []
    c = capacidad
    for i in range(n, 0, -1):
        if mejor[i][c] != mejor[i - 1][c]:
            nombre, peso, _ = objetos[i - 1]
            elegidos.append(nombre)
            c -= peso
    elegidos.reverse()
    return mejor[n][capacidad], elegidos

