        for j in range(1, m + 1):
            if a[i - 1] == b[j - 1]:
                L[i][j] = L[i - 1][j - 1] + 1
            else:
                L[i][j] = max(L[i - 1][j], L[i][j - 1])
    # Reconstrucción desde la esquina inferior derecha
    partes = []
    i, j = n, m
    while i > 0 and j > 0:
        if a[i - 1] == b[j - 1]:
            partes.append(a[i - 1])
            i -= 1
            j -= 1
        elif L[i - 1][j] >= L[i][j - 1]:
            i -= 1
        else:
            j -= 1
    return "".join(reversed(partes))

def combinaciones_suma(candidatos, objetivo):
    ordenados = sorted(candidatos)
    resultado = []
    actual = []

    def explorar(inicio, restante):
        if restante == 0:
            resultado.append(actual[:])          # copia: actual seguirá cambiando
            return
        for i in range(inicio, len(ordenados)):
            valor = ordenados[i]
            if valor > restante:
                break                            # poda: los siguientes son aún mayores
            if i > inicio and valor == ordenados[i - 1]:
                continue                         # mismo valor en el mismo nivel: repetiría
            actual.append(valor)                 # elegir
            explorar(i + 1, restante - valor)    # explorar
            actual.pop()                         # deshacer

    explorar(0, objetivo)
    return resultado

