import heapq
from collections import defaultdict, deque


class RedDeMetro:
    def __init__(self):
        self._vecinos = defaultdict(dict)        # estación -> {vecina: minutos}

    def agregar_tramo(self, a, b, minutos):
        if a == b:
            raise ValueError("Un tramo necesita dos estaciones distintas")
        if minutos <= 0:
            raise ValueError("Los minutos deben ser positivos")
        self._vecinos[a][b] = minutos
        self._vecinos[b][a] = minutos

    def _comprobar(self, *estaciones):
        for estacion in estaciones:
            if estacion not in self._vecinos:    # 'in' no crea claves en el defaultdict
                raise KeyError(estacion)

    def estaciones(self):
        return sorted(self._vecinos)

    def alcanzables(self, origen):
        self._comprobar(origen)
        vistas = {origen}
        pila = [origen]
        while pila:                              # DFS iterativo
            actual = pila.pop()
            for vecina in self._vecinos[actual]:
                if vecina not in vistas:
                    vistas.add(vecina)
                    pila.append(vecina)
        return vistas

    def menos_paradas(self, origen, destino):
        self._comprobar(origen, destino)
        padres = {origen: None}
        cola = deque([origen])
        while cola:                              # BFS
            actual = cola.popleft()
            if actual == destino:
                return self._reconstruir(padres, destino)
            for vecina in self._vecinos[actual]:
                if vecina not in padres:
                    padres[vecina] = actual
                    cola.append(vecina)
        return None

    def ruta_mas_rapida(self, origen, destino):
        self._comprobar(origen, destino)
        distancia = {origen: 0}
        padres = {origen: None}
        cola = [(0, origen)]
        while cola:                              # Dijkstra
            d, actual = heapq.heappop(cola)
            if d > distancia[actual]:
                continue                         # entrada obsoleta
            if actual == destino:
                return d, self._reconstruir(padres, destino)
            for vecina, minutos in self._vecinos[actual].items():
                nueva = d + minutos
                if nueva < distancia.get(vecina, float("inf")):
                    distancia[vecina] = nueva
                    padres[vecina] = actual
                    heapq.heappush(cola, (nueva, vecina))
        return None

    def zonas(self):
        resultado = []
        asignadas = set()
        for estacion in sorted(self._vecinos):
            if estacion not in asignadas:
                zona = self.alcanzables(estacion)
                asignadas |= zona
                resultado.append(sorted(zona))
        return resultado

    @staticmethod
    def _reconstruir(padres, destino):
        camino = []
        nodo = destino
        while nodo is not None:
            camino.append(nodo)
            nodo = padres[nodo]
        camino.reverse()
        return camino

