import bisect
import heapq
import math
from collections import Counter, deque


class MonitorLatencias:
    def __init__(self, ventana=100):
        if not isinstance(ventana, int) or ventana < 1:
            raise ValueError("La ventana debe ser un entero >= 1")
        self._instantes = []                     # ya llegan ordenados
        self._peticiones = []                    # (ms, endpoint, instante) en orden de llegada
        self._ordenadas = []                     # latencias ordenadas, para percentiles
        self._por_endpoint = Counter()
        self._recientes = deque(maxlen=ventana)
        self._suma_recientes = 0

    def registrar(self, instante, endpoint, ms):
        if ms < 0:
            raise ValueError("La latencia no puede ser negativa")
        if self._instantes and instante < self._instantes[-1]:
            raise ValueError("Las peticiones deben llegar en orden cronológico")
        self._instantes.append(instante)
        self._peticiones.append((ms, endpoint, instante))
        bisect.insort(self._ordenadas, ms)
        self._por_endpoint[endpoint] += 1
        if len(self._recientes) == self._recientes.maxlen:
            self._suma_recientes -= self._recientes[0]   # va a salir por la izquierda
        self._recientes.append(ms)
        self._suma_recientes += ms

    def total(self):
        return len(self._instantes)

    def en_intervalo(self, desde, hasta):
        if desde > hasta:
            return 0
        izquierda = bisect.bisect_left(self._instantes, desde)
        derecha = bisect.bisect_right(self._instantes, hasta)
        return derecha - izquierda

    def media_reciente(self):
        if not self._recientes:
            return None
        return self._suma_recientes / len(self._recientes)

    def mas_lentas(self, k):
        # nlargest equivale a sorted(..., reverse=True)[:k], que es estable
        return heapq.nlargest(k, self._peticiones, key=lambda peticion: peticion[0])

    def endpoints_populares(self, k):
        return self._por_endpoint.most_common(k)

    def percentil(self, p):
        if not self._ordenadas:
            raise ValueError("No hay datos")
        if not 0 < p <= 100:
            raise ValueError("p debe estar en (0, 100]")
        rango = math.ceil(p * len(self._ordenadas) / 100)
        return self._ordenadas[rango - 1]

